/* Perpetuity Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="perpetuity-light"] {
  --background: rgb(231, 241, 241);
  --foreground: rgb(15, 75, 85);
  --card: rgb(238, 247, 247);
  --card-foreground: rgb(15, 75, 85);
  --popover: rgb(238, 247, 247);
  --popover-foreground: rgb(15, 75, 85);
  --primary: rgb(24, 132, 140);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(214, 233, 233);
  --secondary-foreground: rgb(15, 75, 85);
  --muted: rgb(225, 234, 234);
  --muted-foreground: rgb(65, 121, 125);
  --accent: rgb(200, 228, 230);
  --accent-foreground: rgb(15, 75, 85);
  --destructive: rgb(208, 55, 55);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(204, 223, 225);
  --input: rgb(214, 233, 233);
  --ring: rgb(24, 132, 140);
  --chart-1: rgb(24, 132, 140);
  --chart-2: rgb(39, 158, 166);
  --chart-3: rgb(48, 182, 190);
  --chart-4: rgb(90, 199, 207);
  --chart-5: rgb(134, 215, 221);
  --radius: 0.125rem;
  --sidebar: rgb(217, 236, 238);
  --sidebar-foreground: rgb(15, 75, 85);
  --sidebar-primary: rgb(24, 132, 140);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(200, 228, 230);
  --sidebar-accent-foreground: rgb(15, 75, 85);
  --sidebar-border: rgb(204, 223, 225);
  --sidebar-ring: rgb(24, 132, 140);
  --font-sans: Courier New, monospace;
  --font-serif: Courier New, monospace;
  --font-mono: Courier New, monospace;
  --shadow-color: rgba(23, 121, 130, 0.15);
  --shadow-opacity: 0.15;
  --shadow-blur: 2px;
  --shadow-spread: 0px;
  --shadow-offset-x: 1px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 1px 1px 2px 0px hsl(185 70% 30% / 0.07);
  --shadow-xs: 1px 1px 2px 0px hsl(185 70% 30% / 0.07);
  --shadow-sm:
    1px 1px 2px 0px hsl(185 70% 30% / 0.15),
    1px 1px 2px -1px hsl(185 70% 30% / 0.15);
  --shadow:
    1px 1px 2px 0px hsl(185 70% 30% / 0.15),
    1px 1px 2px -1px hsl(185 70% 30% / 0.15);
  --shadow-md:
    1px 1px 2px 0px hsl(185 70% 30% / 0.15),
    1px 2px 4px -1px hsl(185 70% 30% / 0.15);
  --shadow-lg:
    1px 1px 2px 0px hsl(185 70% 30% / 0.15),
    1px 4px 6px -1px hsl(185 70% 30% / 0.15);
  --shadow-xl:
    1px 1px 2px 0px hsl(185 70% 30% / 0.15),
    1px 8px 10px -1px hsl(185 70% 30% / 0.15);
  --shadow-2xl: 1px 1px 2px 0px hsl(185 70% 30% / 0.38);
  --tracking-normal: 0em;
}

/* Dark mode */
[data-theme="perpetuity-dark"] {
  --background: rgb(14, 26, 31);
  --foreground: rgb(69, 232, 232);
  --card: rgb(10, 32, 38);
  --card-foreground: rgb(69, 232, 232);
  --popover: rgb(10, 32, 38);
  --popover-foreground: rgb(69, 232, 232);
  --primary: rgb(69, 232, 232);
  --primary-foreground: rgb(14, 26, 31);
  --secondary: rgb(17, 74, 87);
  --secondary-foreground: rgb(69, 232, 232);
  --muted: rgb(16, 48, 57);
  --muted-foreground: rgb(49, 165, 165);
  --accent: rgb(17, 74, 87);
  --accent-foreground: rgb(69, 232, 232);
  --destructive: rgb(234, 60, 60);
  --destructive-foreground: rgb(242, 242, 242);
  --border: rgb(17, 74, 87);
  --input: rgb(17, 74, 87);
  --ring: rgb(69, 232, 232);
  --chart-1: rgb(69, 232, 232);
  --chart-2: rgb(49, 165, 165);
  --chart-3: rgb(53, 137, 137);
  --chart-4: rgb(31, 89, 94);
  --chart-5: rgb(5, 55, 60);
  --radius: 0.125rem;
  --sidebar: rgb(14, 26, 31);
  --sidebar-foreground: rgb(69, 232, 232);
  --sidebar-primary: rgb(69, 232, 232);
  --sidebar-primary-foreground: rgb(14, 26, 31);
  --sidebar-accent: rgb(17, 74, 87);
  --sidebar-accent-foreground: rgb(69, 232, 232);
  --sidebar-border: rgb(17, 74, 87);
  --sidebar-ring: rgb(69, 232, 232);
  --font-sans: Source Code Pro, monospace;
  --font-serif: Source Code Pro, monospace;
  --font-mono: Source Code Pro, monospace;
  --shadow-color: rgba(82, 224, 224, 0.2);
  --shadow-opacity: 0.2;
  --shadow-blur: 2px;
  --shadow-spread: 0px;
  --shadow-offset-x: 1px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 1px 1px 2px 0px hsl(180 70% 60% / 0.1);
  --shadow-xs: 1px 1px 2px 0px hsl(180 70% 60% / 0.1);
  --shadow-sm:
    1px 1px 2px 0px hsl(180 70% 60% / 0.2),
    1px 1px 2px -1px hsl(180 70% 60% / 0.2);
  --shadow:
    1px 1px 2px 0px hsl(180 70% 60% / 0.2),
    1px 1px 2px -1px hsl(180 70% 60% / 0.2);
  --shadow-md:
    1px 1px 2px 0px hsl(180 70% 60% / 0.2),
    1px 2px 4px -1px hsl(180 70% 60% / 0.2);
  --shadow-lg:
    1px 1px 2px 0px hsl(180 70% 60% / 0.2),
    1px 4px 6px -1px hsl(180 70% 60% / 0.2);
  --shadow-xl:
    1px 1px 2px 0px hsl(180 70% 60% / 0.2),
    1px 8px 10px -1px hsl(180 70% 60% / 0.2);
  --shadow-2xl: 1px 1px 2px 0px hsl(180 70% 60% / 0.5);
}
